using System;
using System.Numerics;

// 좌표 규약: +X 가 오른쪽, +Y 가 위쪽인 2D 평면 (수학 좌표계).
// 부호 규약: 반시계 방향(CCW, 왼쪽으로 도는 방향)이 양수.
public static class TurretMath
{
    // 3D 외적 (ax, ay, 0) x (bx, by, 0) 의 z 성분. 값은 |a||b|sin(theta).
    public static float Cross(Vector2 a, Vector2 b) => a.X * b.Y - a.Y * b.X;

    public static int TurnDirection(Vector2 turretPos, Vector2 turretForward, Vector2 targetPos)
    {
        Vector2 toTarget = targetPos - turretPos; // 위치가 아니라 "포탑에서 타깃으로 가는 방향"
        float cross = Cross(turretForward, toTarget);
        if (cross > 0f) return 1;   // 타깃이 왼쪽
        if (cross < 0f) return -1;  // 타깃이 오른쪽
        // 일직선: 내적으로 앞/뒤를 가른다. 뒤면 왼쪽으로 돈다고 약속.
        return Vector2.Dot(turretForward, toTarget) < 0f ? 1 : 0;
    }

    public static float SignedAngleDegrees(Vector2 from, Vector2 to)
    {
        float cross = Cross(from, to);      // |a||b|sin
        float dot = Vector2.Dot(from, to);  // |a||b|cos
        // 일직선(또는 영벡터)은 직접 처리한다.
        // cross 가 -0 이면 Atan2(-0, 음수) 가 -180 을 돌려줘 범위 (-180, 180] 이 깨진다.
        if (cross == 0f) return dot < 0f ? 180f : 0f;
        // Atan2 는 두 인자의 공통 배율(|a||b|)에 영향받지 않으므로 정규화가 필요 없다.
        return MathF.Atan2(cross, dot) * (180f / MathF.PI);
    }
}

