            ?? Angle(V(0f, 1f), V(1f, 0f), -90f, Eps)
            ?? Angle(V(1f, 0f), V(1f, 1f), 45f, Eps)
            ?? Angle(V(1f, 0f), V(1f, -1f), -45f, Eps)
