            ?? Angle(V(3f, 0f), V(0f, 0.5f), 90f, Eps)
            ?? Angle(V(-1f, -1f), V(-1f, 1f), -90f, Eps)
            ?? Angle(V(1f, 0f), V(-1f, 1f), 135f, Eps));

        Run("signed-angle-range", () =>
            Angle(V(1f, 0f), V(-1f, 0f), 180f, Eps)
            ?? Angle(V(0f, 1f), V(0f, -1f), 180f, Eps)
            ?? Angle(V(0f, 2f), V(0f, -0.5f), 180f, Eps)
            ?? Angle(V(1f, 0f), V(-1f, -0.001f), -179.9427f, 0.01f)
            ?? Angle(V(1f, 0f), V(-1f, 0.001f), 179.9427f, 0.01f)
            ?? Angle(V(2f, 2f), V(5f, 5f), 0f, Eps)
            ?? Angle(V(0f, 0f), V(1f, 0f), 0f, Eps)
            ?? Angle(V(1f, 0f), V(0f, 0f), 0f, Eps));

        Run("angle-matches-turn", () =>
        {
            var rng = new System.Random(606);
            for (int i = 0; i < 2000; i++)
            {
                var pos = V(rng.Next(-20, 21), rng.Next(-20, 21));
                var fwd = V(rng.Next(-5, 6), rng.Next(-5, 6));
                var target = V(rng.Next(-20, 21), rng.Next(-20, 21));
                int turn = TurretMath.TurnDirection(pos, fwd, target);
                float ang = TurretMath.SignedAngleDegrees(fwd, target - pos);
                int sign = ang > 0f ? 1 : (ang < 0f ? -1 : 0);
                if (turn != sign) return "포탑 " + pos + ", forward " + fwd + ", 타깃 " + target + ": TurnDirection 은 " + turn + " 인데 SignedAngleDegrees 는 " + ang;
                if (!(ang > -180f && ang <= 180f)) return "범위 (-180, 180] 밖: " + ang;
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int i = 0; i < 3000; i++)
            {
                double a0 = rng.NextDouble() * 360 - 180, a1 = rng.NextDouble() * 360 - 180;
                double l0 = 0.01 + rng.NextDouble() * 50, l1 = 0.01 + rng.NextDouble() * 50;
                var from = V((float)(System.Math.Cos(a0 * System.Math.PI / 180) * l0), (float)(System.Math.Sin(a0 * System.Math.PI / 180) * l0));
                var to = V((float)(System.Math.Cos(a1 * System.Math.PI / 180) * l1), (float)(System.Math.Sin(a1 * System.Math.PI / 180) * l1));
                // 기준 구현: 두 벡터의 절대 각도 차이를 (-180, 180] 로 접는다
                double r = (System.Math.Atan2(to.Y, to.X) - System.Math.Atan2(from.Y, from.X)) * 180 / System.Math.PI;
                while (r > 180) r -= 360;
                while (r <= -180) r += 360;
                if (System.Math.Abs(r) > 179.5) continue; // 접히는 지점 근처는 제외
                string e = Angle(from, to, (float)r, 0.01f);
                if (e != null) return "무작위 #" + i + ": " + e;
                int turn = TurretMath.TurnDirection(V(0f, 0f), from, to);
                if (System.Math.Abs(r) > 0.5 && turn != (r > 0 ? 1 : -1)) return "무작위 #" + i + ": forward " + from + ", 타깃 " + to + " → TurnDirection 기대 " + (r > 0 ? 1 : -1) + " / 결과 " + turn;
            }
            return null;
        });
    }
}

