    static string S(Aabb b) { return "[" + b.Min + " ~ " + b.Max + "]"; }

    // a, b 순서를 바꿔도 결과가 같아야 한다
    static string Box(string what, Aabb a, Aabb b, bool expected)
    {
        bool g1 = Collision2D.AabbOverlap(a, b), g2 = Collision2D.AabbOverlap(b, a);
        if (g1 != expected) return what + ": " + S(a) + " vs " + S(b) + " → 기대 " + expected + " / 결과 " + g1;
        if (g2 != expected) return what + " (인자 순서를 바꿈): " + S(b) + " vs " + S(a) + " → 기대 " + expected + " / 결과 " + g2;
        return null;
    }

    static string Circle(string what, float cx, float cy, float r, Aabb box, bool expected)
    {
        bool got = Collision2D.CircleAabbOverlap(V(cx, cy), r, box);
        return got == expected ? null : what + ": 원 중심 (" + cx + ", " + cy + ") 반지름 " + r + " vs 상자 " + S(box) + " → 기대 " + expected + " / 결과 " + got;
    }

