using System;
using System.Numerics;

public static class Hitscan
{
    // 반직선 P(t) = origin + t * direction (t >= 0) 을 구의 식 |P - center|^2 = r^2 에 대입하면
    //   a t^2 + 2 b t + c = 0,  a = d.d,  b = oc.d,  c = oc.oc - r^2   (oc = origin - center)
    // b 를 "절반 계수"로 잡았으므로 판별식은 b^2 - a c, 해는 (-b ± sqrt(disc)) / a 이다.
    public static bool RaySphere(Vector3 origin, Vector3 direction, Vector3 center, float radius, out float distance)
    {
        distance = 0f;
        float a = direction.LengthSquared();
        if (a == 0f || !(radius >= 0f)) return false;   // 방향 없음 / 잘못된 반지름

        Vector3 oc = origin - center;
        float c = oc.LengthSquared() - radius * radius;
        if (c <= 0f) return true;                       // 시작점이 구 안(또는 표면): 거리 0

        float b = Vector3.Dot(oc, direction);
        if (b >= 0f) return false;                      // 구 밖에서 멀어지는 중: 두 해 모두 음수

        float disc = b * b - a * c;
        if (disc < 0f) return false;                    // 빗나감 (disc == 0 은 접선 명중)

        // 여기서는 b < 0, c > 0 이라 두 해가 모두 양수다. 작은 쪽이 들어가는 지점.
        float t = (-b - MathF.Sqrt(disc)) / a;
        distance = t * MathF.Sqrt(a);                   // 매개변수 t 를 월드 거리로: |direction| 배
        return true;
    }
}

