                double len = System.Math.Sqrt((double)input.X * input.X + (double)input.Y * input.Y);
                double k = len > 1.0 ? 1.0 / len : 1.0;
                string e = Near("무작위 #" + i + " MoveDirection(" + input + ")", PlayerMovement.MoveDirection(input), (float)(input.X * k), (float)(input.Y * k), 1e-3f)
                    ?? Near("무작위 #" + i + " ComputeVelocity(" + input + ", " + (float)speed + ")", PlayerMovement.ComputeVelocity(input, (float)speed), (float)(input.X * k * speed), (float)(input.Y * k * speed), 1e-3f);
                if (e != null) return e;
                double ax = rng.Next(-20, 21), ay = rng.Next(-20, 21), vx = rng.Next(-20, 21), vy = rng.Next(-20, 21), force = 1 + rng.NextDouble() * 9;
                double dl = System.Math.Sqrt((vx - ax) * (vx - ax) + (vy - ay) * (vy - ay));
                double kx = dl == 0 ? 0 : (vx - ax) / dl * force, ky = dl == 0 ? 0 : (vy - ay) / dl * force;
                e = Near("무작위 #" + i + " KnockbackVelocity(공격자 <" + ax + ", " + ay + ">, 피격자 <" + vx + ", " + vy + ">, " + (float)force + ")",
                    PlayerMovement.KnockbackVelocity(V((float)ax, (float)ay), V((float)vx, (float)vy), (float)force), (float)kx, (float)ky, 1e-3f);
                if (e != null) return e;
            }
            return null;
        });
    }
}

