problems.solutionCode:
using System;
using System.Numerics;

// 좌표 규약: +X 오른쪽, +Y 위쪽. 각도는 도(degree), 반시계 방향이 양수.
// 각도 결과의 범위는 항상 (-180, 180]. 정확히 반대(180도 차이)는 +180, 반시계로 돈다.
public static class SteeringMath
{
    // current 를 target 쪽으로 최대 maxStep 만큼 이동한 위치.
    public static Vector2 MoveTowards(Vector2 current, Vector2 target, float maxStep)
    {
        if (maxStep < 0f) maxStep = 0f;
        Vector2 offset = target - current;
        float distSq = offset.LengthSquared();
        // 도착 판정은 제곱끼리 비교한다. 같은 위치(distSq == 0)도 여기서 걸러져 0 으로 나누지 않는다.
        if (distSq <= maxStep * maxStep) return target;
        float dist = MathF.Sqrt(distSq);
        return current + offset * (maxStep / dist);
    }

    // 임의의 각도를 (-180, 180] 범위로.
    public static float WrapAngle(float degrees)
    {
        float a = degrees % 360f;          // C# 의 % 는 피제수의 부호를 따른다: 결과는 (-360, 360)
        if (a > 180f) a -= 360f;           // (180, 360)   → (-180, 0)
        else if (a <= -180f) a += 360f;    // (-360, -180] → (0, 180]   (-180 은 +180 이 된다)
        return a;
    }

    // fromDeg 에서 toDeg 로 가는 가장 짧은 부호 있는 각도 차.
    public static float DeltaAngle(float fromDeg, float toDeg)
    {
        return WrapAngle(toDeg - fromDeg);
    }

    // currentDeg 를 targetDeg 쪽으로 짧은 방향을 따라 최대 maxStepDeg 만큼 돌린 각도.
    public static float MoveTowardsAngle(float currentDeg, float targetDeg, float maxStepDeg)
    {
        if (maxStepDeg < 0f) maxStepDeg = 0f;
        float delta = DeltaAngle(currentDeg, targetDeg);
        if (MathF.Abs(delta) <= maxStepDeg) return WrapAngle(targetDeg);   // 도착: 목표 그 자체
        float step = delta > 0f ? maxStepDeg : -maxStepDeg;                // 정확히 반대(+180)는 반시계
        return WrapAngle(currentDeg + step);
    }

    // 방향 벡터 currentDir 을 targetDir 방향으로 최대 maxStepDeg 만큼 회전한다.
    public static Vector2 RotateTowards(Vector2 currentDir, Vector2 targetDir, float maxStepDeg)
    {
        float currentLenSq = currentDir.LengthSquared();
        float targetLenSq = targetDir.LengthSquared();
        if (currentLenSq == 0f || targetLenSq == 0f) return currentDir;
        if (maxStepDeg < 0f) maxStepDeg = 0f;

        // 부호 있는 사이각: 외적 = |a||b|sin, 내적 = |a||b|cos. 정규화 없이 Atan2 에 넣는다.
        float cross = currentDir.X * targetDir.Y - currentDir.Y * targetDir.X;
        float dot = Vector2.Dot(currentDir, targetDir);
        float angle;
        if (cross == 0f) angle = dot < 0f ? 180f : 0f;   // 일직선(-0 포함): 정반대는 +180 으로 고정
        else angle = MathF.Atan2(cross, dot) * (180f / MathF.PI);

        if (MathF.Abs(angle) <= maxStepDeg)
        {
            // 도착: 목표 방향 그 자체를 쓰고 길이만 current 에 맞춘다.
            return targetDir * MathF.Sqrt(currentLenSq / targetLenSq);
        }

        float radians = (angle > 0f ? maxStepDeg : -maxStepDeg) * (MathF.PI / 180f);
        float c = MathF.Cos(radians);
        float s = MathF.Sin(radians);
        // 반시계 회전: (x cos - y sin, x sin + y cos). 회전은 길이를 바꾸지 않는다.
        return new Vector2(currentDir.X * c - currentDir.Y * s, currentDir.X * s + currentDir.Y * c);
    }
}

