            ?? Delta(1080f, 90f, 90f) ?? Delta(-725f, 0f, 5f) ?? Delta(0f, 3600090f, 90f) ?? Delta(45f, 45f, 0f));

        Run("angle-step-wrap", () =>
            Step(0f, 90f, 30f, 30f)
            ?? Step(0f, -90f, 30f, -30f)
            ?? Step(350f, 10f, 5f, -5f)
            ?? Step(10f, 350f, 5f, 5f)
            ?? Step(170f, -170f, 5f, 175f)
            ?? Step(-170f, 170f, 5f, -175f)
