            ?? StepExact(80f, 90f, 10f, 90f)
            ?? StepExact(350f, 10f, 45f, 10f)
            ?? StepExact(10f, 730f, 45f, 10f)
            ?? StepExact(0f, 270f, 300f, -90f)
            ?? StepExact(175f, -180f, 20f, 180f)
            ?? StepExact(33.3f, -70.1f, 150f, -70.1f)
            ?? StepExact(350.2f, 10.3f, 45f, 10.3f)
            ?? StepExact(190f, 190f, 0f, -170f)
            ?? StepExact(370f, 0f, 0f, 10f)
            ?? StepExact(20f, 100f, -5f, 20f));

        Run("rotate-dir", () =>
            Rot(V(1f, 0f), V(0f, 1f), 30f, 0.8660254f, 0.5f)
            ?? Rot(V(1f, 0f), V(0f, -1f), 30f, 0.8660254f, -0.5f)
            ?? Rot(V(0f, 2f), V(-3f, 0f), 45f, -1.4142136f, 1.4142136f)
            ?? Rot(V(1f, 0f), V(0f, 5f), 120f, 0f, 1f)
            ?? Rot(V(3f, 0f), V(0f, -0.5f), 100f, 0f, -3f)
            ?? Rot(V(2f, 0f), V(5f, 0f), 10f, 2f, 0f)
            ?? Rot(V(1f, 0f), V(-1f, 0f), 90f, 0f, 1f)
            ?? Rot(V(0f, 1f), V(0f, -1f), 90f, -1f, 0f)
            ?? Rot(V(1f, 0f), V(-2f, 0f), 180f, -1f, 0f)
            ?? Rot(V(0f, 0f), V(1f, 0f), 30f, 0f, 0f)
            ?? Rot(V(1f, 2f), V(0f, 0f), 30f, 1f, 2f)
            ?? Rot(V(1f, 2f), V(-2f, 1f), 0f, 1f, 2f)
            ?? Rot(V(1f, 2f), V(-2f, 1f), -15f, 1f, 2f));

        Run("simulate-no-overshoot", () =>
        {
            // 위치: (-7,2) → (20,-11), 거리 sqrt(898) ≈ 29.967, 스텝 0.75 → 40번째 스텝에 도착
            var pos = V(-7f, 2f); var goal = V(20f, -11f);
            float prev = System.Numerics.Vector2.Distance(pos, goal);
            int arrived = -1;
            for (int i = 1; i <= 50; i++)
            {
                pos = SteeringMath.MoveTowards(pos, goal, 0.75f);
                float d = System.Numerics.Vector2.Distance(pos, goal);
                if (!(d <= prev)) return "위치 스텝 " + i + ": 목표까지 거리가 늘어남 " + prev + " → " + d + " (지나침)";
                if (arrived < 0 && pos == goal) arrived = i;
                if (arrived >= 0 && pos != goal) return "위치 스텝 " + i + ": 도착한 뒤 목표에서 벗어남 " + pos;
                prev = d;
            }
            if (arrived != 40) return "위치: 40번째 스텝에 정확히 도착해야 함 / 결과 " + (arrived < 0 ? "도착하지 못함" : arrived + "번째");

            // 각도: 170 → -100 (최단 +90, 180 경계를 넘는다), 스텝 7 → 13번째 스텝에 도착
            float ang = 170f; double left = 90.0; arrived = -1;
            for (int i = 1; i <= 20; i++)
            {
                ang = SteeringMath.MoveTowardsAngle(ang, -100f, 7f);
                string e = InRange("각도 스텝 " + i, ang); if (e != null) return e;
                double now = System.Math.Abs(RefDelta(ang, -100.0));
                if (!(now <= left + 1e-3)) return "각도 스텝 " + i + ": 남은 각도가 늘어남 " + left + " → " + now + " (먼 쪽으로 돌았거나 지나침)";
                if (arrived < 0 && ang == -100f) arrived = i;
                if (arrived >= 0 && ang != -100f) return "각도 스텝 " + i + ": 도착한 뒤 목표에서 벗어남 " + ang;
                left = now;
            }
            if (arrived != 13) return "각도: 13번째 스텝에 정확히 도착해야 함 / 결과 " + (arrived < 0 ? "도착하지 못함" : arrived + "번째");

            // 방향: (1,0) → 100도 방향(길이 3), 스텝 7 → 15번째 스텝에 도착, 길이 1 유지
            var dir = V(1f, 0f);
            var tgt = V((float)(3 * System.Math.Cos(100 * System.Math.PI / 180)), (float)(3 * System.Math.Sin(100 * System.Math.PI / 180)));
            for (int i = 1; i <= 20; i++)
            {
                dir = SteeringMath.RotateTowards(dir, tgt, 7f);
                double a = System.Math.Atan2(dir.Y, dir.X) * 180 / System.Math.PI;
                double want = i < 15 ? 7.0 * i : 100.0;
                if (!(System.Math.Abs(a - want) <= 0.01)) return "방향 스텝 " + i + ": 각도 기대 " + want + " / 결과 " + a.ToString("F4");
                if (!(System.Math.Abs(dir.Length() - 1f) <= 1e-3f)) return "방향 스텝 " + i + ": 길이가 유지되지 않음 " + dir.Length();
            }
            return null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int i = 0; i < 3000; i++)
            {
                // 각도: 0.5 의 배수라 float 로 정확히 표현된다
                double c = rng.Next(-1440, 1441) * 0.5, t = rng.Next(-1440, 1441) * 0.5, step = rng.Next(1, 400) * 0.5;
                double d = RefDelta(c, t);
                if (System.Math.Abs(d) <= 179.0)
                {
                    float gd = SteeringMath.DeltaAngle((float)c, (float)t);
                    if (!(System.Math.Abs(gd - d) <= AngEps)) return "무작위 #" + i + ": DeltaAngle(" + c + ", " + t + ") → 기대 " + d + " / 결과 " + gd;
                    double want = System.Math.Abs(d) <= step ? t : c + System.Math.Sign(d) * step;
                    float got = SteeringMath.MoveTowardsAngle((float)c, (float)t, (float)step);
                    string e = InRange("무작위 #" + i + ": MoveTowardsAngle(" + c + ", " + t + ", " + step + ")", got);
                    if (e != null) return e;
                    if (!(Mod360Diff(got, want) <= AngEps)) return "무작위 #" + i + ": MoveTowardsAngle(" + c + ", " + t + ", " + step + ") → 기대 " + RefDelta(0, want) + " (360도 주기로 같은 각) / 결과 " + got;
                }

                // 방향 벡터
                double a0 = rng.NextDouble() * 360 - 180, a1 = rng.NextDouble() * 360 - 180, l0 = 0.5 + rng.NextDouble() * 5, l1 = 0.5 + rng.NextDouble() * 5, rs = 1 + rng.NextDouble() * 89;
                double rd = RefDelta(a0, a1);
                if (System.Math.Abs(rd) <= 179.0 && System.Math.Abs(System.Math.Abs(rd) - rs) >= 0.05)
                {
                    double wa = (System.Math.Abs(rd) <= rs ? a1 : a0 + System.Math.Sign(rd) * rs) * System.Math.PI / 180;
                    var cur = V((float)(l0 * System.Math.Cos(a0 * System.Math.PI / 180)), (float)(l0 * System.Math.Sin(a0 * System.Math.PI / 180)));
                    var tg = V((float)(l1 * System.Math.Cos(a1 * System.Math.PI / 180)), (float)(l1 * System.Math.Sin(a1 * System.Math.PI / 180)));
                    string e = NearV("무작위 #" + i + ": RotateTowards(" + cur + ", " + tg + ", " + (float)rs + ")", SteeringMath.RotateTowards(cur, tg, (float)rs), (float)(l0 * System.Math.Cos(wa)), (float)(l0 * System.Math.Sin(wa)), 2e-3f);
                    if (e != null) return e;
                }

                // 위치
                double px = rng.Next(-30, 31), py = rng.Next(-30, 31), qx = rng.Next(-30, 31), qy = rng.Next(-30, 31), ms = 0.25 + rng.NextDouble() * 20;
                double dist = System.Math.Sqrt((qx - px) * (qx - px) + (qy - py) * (qy - py));
                if (System.Math.Abs(dist - ms) >= 1e-3)
                {
                    double k = dist <= ms ? 1.0 : ms / dist;
                    string e = NearV("무작위 #" + i + ": MoveTowards(<" + px + ", " + py + ">, <" + qx + ", " + qy + ">, " + (float)ms + ")",
                        SteeringMath.MoveTowards(V((float)px, (float)py), V((float)qx, (float)qy), (float)ms), (float)(px + (qx - px) * k), (float)(py + (qy - py) * k), 2e-3f);
                    if (e != null) return e;
                }
            }
            return null;
        });
    }
}
